-// A todo has: id, title, done, createdAt. No due date, no tags, no owner.
-// Saving and importing decisions live in backup.js (persist, importBackup); this file only wires them to the page.
+// A todo has: id, title, done, createdAt, and maybe dueDate (YYYY-MM-DD, no key when there is none). No tags, no owner.
+// Saving and importing live in backup.js (persist, importBackup), due dates in due.js; this file only wires them to the page.
 let todos = store.load().todos;
 let filter = 'all';
+// 'added' (the order of `todos`) or 'due'. Not saved: a reload goes back to 'added' (A11). Sorting never reorders `todos` (Q6).
+let sort = 'added';
+// A due date was saved since the last render(): the list is redrawn when the date field is left, not while typing (Q3).
+let dirty = false;
 // The one Undo of the app (plan han-chot-cho-viec, Q7): { restore, timer } while the "Hoàn tác" button shows, else null.
 // Kept in page memory only, never saved.
 let undo = null;
@@ -9,11 +13,40 @@ const UNDO_MS = 10000;

 const $ = (sel) => document.querySelector(sel);

-function add(title) {
-  todos.push({ id: crypto.randomUUID(), title: title.trim(), done: false, createdAt: Date.now() });
+function add(title, dueDate) {
+  const t = { id: crypto.randomUUID(), title: title.trim(), done: false, createdAt: Date.now() };
+  if (isValidDueDate(dueDate)) t.dueDate = dueDate; // an empty field gives '' and no key (AC2); a past day is fine (A4)
+  todos.push(t);
   commit();
 }

+// On `change` of a row's date field. Only a valid, different day is saved: while a day is typed with the keyboard the field
+// goes '' after a Backspace, and that must not drop the saved due date (Q3). Saves now; the caller redraws only its row.
+function setDue(id, value) {
+  const t = todos.find((x) => x.id === id);
+  if (!t || !isValidDueDate(value) || t.dueDate === value) return null;
+  t.dueDate = value;
+  dirty = true;
+  save();
+  return t;
+}
+
+// On `blur` of a row's date field when it is empty. before = its value on focus. A broken saved value is kept (A14).
+function clearDue(id, before) {
+  const t = todos.find((x) => x.id === id);
+  if (!t || !isValidDueDate(t.dueDate)) return;
+  const was = t.dueDate; // the day saved now, which may be one set during this same focus
+  delete t.dueDate;
+  dirty = true;
+  // A day set and cleared within one focus loses nothing that was there before: no D5, no Undo (Q3).
+  if (before === '') return save();
+  const { message } = persist(store, todos);
+  offerUndo(message || DUE_TEXT.cleared.replace('{title}', () => t.title), () => {
+    const x = todos.find((y) => y.id === id); // removed since: nothing to put back
+    if (x) x.dueDate = was;
+  });
+}
+
 function toggle(id) {
   const t = todos.find((x) => x.id === id);
   if (t) t.done = !t.done;
@@ -66,23 +99,51 @@ function undoLast() {
 }

 function visible() {
-  if (filter === 'open') return todos.filter((t) => !t.done);
-  if (filter === 'done') return todos.filter((t) => t.done);
-  return todos;
+  const shown = filter === 'open' ? todos.filter((t) => !t.done) : filter === 'done' ? todos.filter((t) => t.done) : todos;
+  return sort === 'due' ? sortByDue(shown) : shown;
+}
+
+// "Hạn …", "Quá hạn" and the overdue class of one row. "Today" is taken at each call, so it moves on at midnight (F3).
+function drawDue(li, t) {
+  const overdue = isOverdue(t, localDateString(new Date()));
+  li.className = [t.done && 'done', overdue && 'overdue'].filter(Boolean).join(' ');
+  li.querySelector('.due').textContent = isValidDueDate(t.dueDate) ? formatDueDate(t.dueDate) : '';
+  li.querySelector('.overdue-tag').textContent = overdue ? DUE_TEXT.overdue : '';
 }

-function render() {
+// focusTo: the element that has or is about to get focus. When it is a control of a row, the same control of the same todo
+// gets focus in the new list, so a keyboard user is not sent back to the top of the page (AC9, U5).
+function render(focusTo = document.activeElement) {
+  const keep = focusTo && focusTo.dataset && focusTo.dataset.part ? { id: focusTo.dataset.id, part: focusTo.dataset.part } : null;
+  let refocus = null;
+  dirty = false;
   const list = $('#list');
   list.innerHTML = '';
   for (const t of visible()) {
     const li = document.createElement('li');
-    li.className = t.done ? 'done' : '';
-    li.innerHTML = `<label><input type="checkbox" ${t.done ? 'checked' : ''}> <span></span></label><button aria-label="Xoá">×</button>`;
+    // No user text in this template (S3): titles go in with textContent, the date label with setAttribute.
+    li.innerHTML = `<label><input type="checkbox" ${t.done ? 'checked' : ''}> <span></span></label>` +
+      '<span class="when"><span class="due"></span><span class="overdue-tag"></span><input type="date"></span>' +
+      '<button aria-label="Xoá">×</button>';
     li.querySelector('span').textContent = t.title;
+    const date = li.querySelector('input[type="date"]');
+    date.value = isValidDueDate(t.dueDate) ? t.dueDate : '';
+    date.setAttribute('aria-label', DUE_TEXT.rowLabel.replace('{title}', () => t.title));
+    date.onfocus = () => { date.dataset.before = date.value; };
+    date.onchange = () => { if (setDue(t.id, date.value)) drawDue(li, t); };
+    date.onblur = (e) => {
+      if (date.value === '') clearDue(t.id, date.dataset.before);
+      if (dirty) render(e.relatedTarget); // the element focus moves to, since activeElement is still this field or body
+    };
     li.querySelector('input').onchange = () => toggle(t.id);
     li.querySelector('button').onclick = () => remove(t.id);
+    const parts = { toggle: li.querySelector('input'), due: date, remove: li.querySelector('button') };
+    for (const [part, el] of Object.entries(parts)) Object.assign(el.dataset, { id: t.id, part });
+    if (keep && keep.id === t.id) refocus = parts[keep.part];
+    drawDue(li, t);
     list.append(li);
   }
+  if (refocus) refocus.focus();
   const open = todos.filter((t) => !t.done).length;
   // Every todo done (and the list not empty): say so instead of "0 việc chưa xong" (Thảo, PR 3).
   $('#count').textContent = open === 0 && todos.length > 0 ? 'Đã xong hết' : `${formatCount(open)} việc chưa xong`;
@@ -105,8 +166,15 @@ function ask(question) {
 $('#add').onsubmit = (e) => {
   e.preventDefault();
   const input = $('#title');
-  if (input.value.trim()) add(input.value);
+  const date = $('#due');
+  if (input.value.trim()) add(input.value, date.value);
   input.value = '';
+  date.value = '';
+};
+
+$('#sort').onchange = (e) => {
+  sort = e.target.value;
+  render();
 };

